// Read-only inspection of the Figma document pages, components, and media assets
async function inspectDocument() {
  const pages = figma.root.children;
  const result = {
    pages: pages.map(p => ({ id: p.id, name: p.name })),
    components: [],
    media: [],
    workspaceId: null
  };

  for (const page of pages) {
    if (page.name.includes("03 · Workspace")) {
      result.workspaceId = page.id;
    }

    if (page.name.includes("02 · Components")) {
      // Find all components/component sets on the components page
      const components = page.findAll(node => node.type === "COMPONENT" || node.type === "COMPONENT_SET");
      result.components = components.map(c => {
        let details = { id: c.id, name: c.name, type: c.type, x: c.x, y: c.y, width: c.width, height: c.height };
        if (c.type === "COMPONENT_SET") {
          details.children = c.children.map(child => ({ id: child.id, name: child.name, type: child.type }));
        }
        return details;
      });
    }

    if (page.name.includes("04 · Media")) {
      // Find components, instances, frames, vectors, or images on the media page
      const mediaNodes = page.findAll(node => node.type === "COMPONENT" || node.type === "COMPONENT_SET" || node.type === "FRAME" || node.type === "INSTANCE" || node.type === "VECTOR" || node.type === "GROUP");
      result.media = mediaNodes
        .filter(n => n.parent && n.parent.type === "PAGE") // only top level nodes on media page
        .map(n => ({ id: n.id, name: n.name, type: n.type, width: n.width, height: n.height }));
    }
  }

  console.log("INSPECTION_RESULT:" + JSON.stringify(result, null, 2));
}

inspectDocument().then(() => figma.close("Inspection completed")).catch(err => figma.close("Error: " + err.message));

// Read-only inspection of the Figma document pages, components, and media assets
async function inspectDocument() {
  const pages = figma.root.children;
  const result = {
    pages: pages.map(p => ({ id: p.id, name: p.name })),
    components: [],
    media: [],
    workspaceId: null
  };

  for (const page of pages) {
    if (page.name.includes("Workspace") || page.name.includes("03")) {
      result.workspaceId = page.id;
    }

    if (page.name.includes("Components") || page.name.includes("02")) {
      const components = page.findAll(node => node.type === "COMPONENT" || node.type === "COMPONENT_SET");
      result.components = components.map(c => {
        let details = { id: c.id, name: c.name, type: c.type, x: c.x, y: c.y, width: c.width, height: c.height };
        if (c.type === "COMPONENT_SET") {
          details.children = c.children.map(child => ({ id: child.id, name: child.name, type: child.type }));
        }
        return details;
      });
    }

    if (page.name.includes("Media") || page.name.includes("04")) {
      const mediaNodes = page.findAll(node => node.parent && node.parent.id === page.id);
      result.media = mediaNodes.map(n => ({ id: n.id, name: n.name, type: n.type, width: n.width, height: n.height }));
    }
  }

  return result;
}

