async function inspectDocument() {
  const pages = figma.root.children;
  const result = {
    pages: pages.map(p => ({ id: p.id, name: p.name })),
    components: [],
    media: [],
    workspaceId: null
  };

  for (const page of pages) {
    if (page.name.includes("Workspace") || page.name.includes("03")) {
      result.workspaceId = page.id;
    }

    if (page.name.includes("Components") || page.name.includes("02")) {
      const components = page.findAll(node => node.type === "COMPONENT" || node.type === "COMPONENT_SET");
      result.components = components.map(c => {
        let details = { id: c.id, name: c.name, type: c.type, width: c.width, height: c.height };
        if (c.type === "COMPONENT_SET") {
          details.children = c.children.map(child => ({ id: child.id, name: child.name, type: child.type }));
        }
        return details;
      });
    }

    if (page.name.includes("Media") || page.name.includes("04")) {
