  // Recolor helper for cloned vectors
  function recolorNode(node, color) {
    if (node.type === "VECTOR" || node.type === "BOOLEAN_OPERATION") {
      node.fills = [{ type: "SOLID", color: color }];
    }
    if ("children" in node) {
      for (const child of node.children) {
        recolorNode(child, color);
      }
    }
  }

